INSERT INTO "sqlite_sequence" ("name","seq") VALUES('d1_migrations',14);
CREATE INDEX trips_rider ON trips(rider_id, created_at);
CREATE INDEX trips_status ON trips(status, updated_at);
CREATE INDEX events_time ON operation_events(created_at);
CREATE UNIQUE INDEX one_live_trip_per_rider ON trips(rider_id) WHERE is_demo=0 AND status IN ('matching','arriving','arrived','riding');
CREATE UNIQUE INDEX one_trip_per_driver ON trips(driver_id) WHERE driver_id IS NOT NULL AND status IN ('arriving','arrived','riding');
CREATE INDEX phone_rate ON phone_challenges(phone,created_at);
CREATE INDEX phone_ip_rate ON phone_challenges(ip_hash,created_at);
CREATE INDEX push_actor ON push_subscriptions(role,actor_id);
CREATE INDEX notifications_actor ON app_notifications(role,actor_id,created_at);
CREATE INDEX account_changes_owner ON account_changes(actor,role,created_at);
CREATE INDEX idx_email_auth_actor ON email_auth_tokens(role,actor,purpose,expires_at);
CREATE INDEX idx_public_phone_otp_actor ON public_phone_otp(role,actor,created_at);
CREATE TRIGGER wallet_funds BEFORE INSERT ON wallet_entries WHEN NEW.enforce_funds=1 AND COALESCE((SELECT balance_halalas FROM wallet_accounts WHERE account_id=NEW.account_id),0)+NEW.amount_halalas<0 BEGIN SELECT RAISE(ABORT,'INSUFFICIENT_FUNDS'); END;
CREATE TRIGGER wallet_balance AFTER INSERT ON wallet_entries BEGIN INSERT INTO wallet_accounts(account_id,balance_halalas) VALUES(NEW.account_id,NEW.amount_halalas) ON CONFLICT(account_id) DO UPDATE SET balance_halalas=balance_halalas+NEW.amount_halalas; END;
CREATE TRIGGER settlement_state BEFORE INSERT ON trip_settlements WHEN (NEW.operation='cancel' AND (SELECT status FROM trips WHERE id=NEW.trip_id) NOT IN ('matching','arriving','arrived')) OR (NEW.operation='complete' AND (SELECT status FROM trips WHERE id=NEW.trip_id)<>'riding') BEGIN SELECT RAISE(ABORT,'TRIP_STATE_CHANGED'); END;
CREATE TRIGGER coupon_limit BEFORE INSERT ON coupon_redemptions WHEN NOT EXISTS(SELECT 1 FROM coupons WHERE code=NEW.code AND active=1 AND expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now')) OR (SELECT count(*) FROM coupon_redemptions WHERE code=NEW.code)>=(SELECT max_uses FROM coupons WHERE code=NEW.code) BEGIN SELECT RAISE(ABORT,'COUPON_UNAVAILABLE'); END;
CREATE TRIGGER otp_rate_limit BEFORE INSERT ON phone_challenges WHEN EXISTS(SELECT 1 FROM phone_challenges WHERE phone=NEW.phone AND created_at>strftime('%Y-%m-%dT%H:%M:%fZ','now','-60 seconds')) OR (SELECT count(*) FROM phone_challenges WHERE phone=NEW.phone AND created_at>strftime('%Y-%m-%dT%H:%M:%fZ','now','-1 hour'))>=5 OR (SELECT count(*) FROM phone_challenges WHERE ip_hash=NEW.ip_hash AND created_at>strftime('%Y-%m-%dT%H:%M:%fZ','now','-1 hour'))>=20 BEGIN SELECT RAISE(ABORT,'RATE_LIMIT'); END;
CREATE TRIGGER enforce_driver_accept BEFORE UPDATE OF driver_id ON trips WHEN NEW.driver_id IS NOT NULL AND NEW.driver_id IS NOT OLD.driver_id AND NEW.status='arriving' AND NEW.is_demo=0 BEGIN SELECT CASE WHEN COALESCE((SELECT balance_halalas FROM wallet_accounts WHERE account_id='captain:'||NEW.driver_id),0)<0 THEN RAISE(ABORT,'NEGATIVE_DRIVER_BALANCE') END; SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM dispatch_offers WHERE trip_id=NEW.id AND captain_id=NEW.driver_id AND expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now')) THEN RAISE(ABORT,'OFFER_EXPIRED') END; END;
CREATE TRIGGER withdrawal_minimum_balance BEFORE INSERT ON withdrawal_requests WHEN COALESCE((SELECT balance_halalas FROM wallet_accounts WHERE account_id='captain:' || NEW.captain_id),0)<5000 BEGIN SELECT RAISE(ABORT,'WITHDRAWAL_MINIMUM_BALANCE'); END;
CREATE TRIGGER validate_matching_expiry BEFORE INSERT ON trip_expiry_claims BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM trips WHERE id=NEW.trip_id AND status='matching' AND is_demo=0 AND julianday(created_at)<=julianday('now','-3 minutes')) THEN RAISE(ABORT,'REQUEST_NOT_EXPIRED') END; END;
CREATE TRIGGER reject_expired_accept BEFORE UPDATE OF driver_id ON trips WHEN NEW.driver_id IS NOT NULL AND NEW.driver_id IS NOT OLD.driver_id AND NEW.status='arriving' AND NEW.is_demo=0 BEGIN SELECT CASE WHEN julianday(OLD.created_at)<=julianday('now','-3 minutes') OR EXISTS(SELECT 1 FROM trip_expiry_claims WHERE trip_id=OLD.id) THEN RAISE(ABORT,'REQUEST_EXPIRED') END; END;
CREATE TRIGGER unique_account_email_insert BEFORE INSERT ON public_accounts WHEN trim(NEW.email)<>'' BEGIN SELECT CASE WHEN EXISTS(SELECT 1 FROM public_accounts WHERE role=NEW.role AND lower(trim(email))=lower(trim(NEW.email))) THEN RAISE(ABORT,'ACCOUNT_EMAIL_EXISTS') END; END;
CREATE TRIGGER unique_account_email_update BEFORE UPDATE OF email ON public_accounts WHEN trim(NEW.email)<>'' AND lower(trim(NEW.email))<>lower(trim(OLD.email)) BEGIN SELECT CASE WHEN EXISTS(SELECT 1 FROM public_accounts WHERE role=NEW.role AND actor<>OLD.actor AND lower(trim(email))=lower(trim(NEW.email))) THEN RAISE(ABORT,'ACCOUNT_EMAIL_EXISTS') END; END;
CREATE TRIGGER unique_captain_email_insert BEFORE INSERT ON captain_applications WHEN trim(NEW.email)<>'' BEGIN SELECT CASE WHEN EXISTS(SELECT 1 FROM captain_applications WHERE lower(trim(email))=lower(trim(NEW.email))) THEN RAISE(ABORT,'CAPTAIN_EMAIL_EXISTS') END; END;
CREATE TRIGGER recovery_consume BEFORE UPDATE OF consumed_at ON account_recovery WHEN NEW.consumed_at IS NOT NULL BEGIN SELECT CASE WHEN OLD.consumed_at IS NOT NULL OR OLD.status<>'approved' OR OLD.expires_at<=strftime('%Y-%m-%dT%H:%M:%fZ','now') THEN RAISE(ABORT,'RECOVERY_EXPIRED') END; END;
CREATE TRIGGER counter_accept_guard BEFORE UPDATE OF status ON fare_counters WHEN NEW.status='accepted' BEGIN SELECT CASE WHEN OLD.status<>'pending' OR OLD.expires_at<=strftime('%Y-%m-%dT%H:%M:%fZ','now') OR NOT EXISTS(SELECT 1 FROM trips t JOIN dispatch_offers o ON o.trip_id=t.id WHERE t.id=OLD.trip_id AND t.status='matching' AND t.driver_id IS NULL AND o.captain_id=OLD.captain_id AND o.expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now')) THEN RAISE(ABORT,'COUNTER_EXPIRED') END; END;
CREATE TRIGGER counter_driver_eligible BEFORE UPDATE OF status ON fare_counters WHEN NEW.status='accepted' BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM captain_applications a JOIN captain_presence p ON p.application_id=a.id WHERE a.id=OLD.captain_id AND a.status='active' AND p.available=1 AND p.accuracy<=150 AND p.location_at>strftime('%Y-%m-%dT%H:%M:%fZ','now','-2 minutes') AND COALESCE((SELECT balance_halalas FROM wallet_accounts WHERE account_id='captain:'||a.id),0)>=0 AND NOT EXISTS(SELECT 1 FROM account_controls co WHERE co.role='captain' AND co.account_id=a.id AND co.suspended=1) AND NOT EXISTS(SELECT 1 FROM trips t WHERE t.driver_id=a.id AND t.status IN ('arriving','arrived','riding'))) THEN RAISE(ABORT,'CAPTAIN_UNAVAILABLE') END; END;
CREATE TRIGGER account_change_consume BEFORE UPDATE OF consumed_at ON account_changes WHEN NEW.consumed_at IS NOT NULL BEGIN SELECT CASE WHEN OLD.consumed_at IS NOT NULL OR OLD.stage<>'approved' OR OLD.expires_at<=strftime('%Y-%m-%dT%H:%M:%fZ','now') OR NOT EXISTS(SELECT 1 FROM public_accounts a WHERE a.actor=OLD.actor AND a.role=OLD.role AND a.phone=OLD.old_phone AND a.password_hash=OLD.old_hash) THEN RAISE(ABORT,'CHANGE_EXPIRED') END; END;
CREATE TRIGGER recharge_once BEFORE UPDATE OF redeemed_by ON recharge_cards WHEN NEW.redeemed_by IS NOT NULL BEGIN SELECT CASE WHEN OLD.redeemed_by IS NOT NULL OR OLD.expires_at<=strftime('%Y-%m-%dT%H:%M:%fZ','now') THEN RAISE(ABORT,'RECHARGE_UNAVAILABLE') END; END;
